CREATE TABLE IF NOT EXISTS "task_email_targets"
(
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "task_id" bigint NOT NULL,
    "email" varchar(255) NOT NULL,
    "status" SMALLINT NOT NULL DEFAULT 0,
    "error" text NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ DEFAULT NULL,
    "updated_at" TIMESTAMPTZ DEFAULT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_task_email_targets_unique"
    ON "task_email_targets" ("task_id", "email");

CREATE INDEX IF NOT EXISTS "idx_task_email_targets_task_status_id"
    ON "task_email_targets" ("task_id", "status", "id");

CREATE INDEX IF NOT EXISTS "idx_user_auth_methods_type_user_identifier"
    ON "user_auth_methods" ("auth_type", "user_id", "auth_identifier");

CREATE INDEX IF NOT EXISTS "idx_user_subscribe_user_status"
    ON "user_subscribe" ("user_id", "status");
